def idle(page):
 end=time.monotonic()+240;stable=0;before=page.evaluate('__probe.draws')
 while time.monotonic()<end:
  page.wait_for_timeout(300);v=page.evaluate("({draws:__probe.draws,pending:__probe.pending.size,hidden:document.querySelector('.nantes-loading').hidden})")
  stable=stable+1 if v['draws']==before and v['pending']==0 and v['hidden'] else 0
  if stable>=3:return
  before=v['draws']
 raise AssertionError('Pas de repos')
