 renders=page.evaluate('(start)=>__probe.renders.filter(t=>t>=start)',start);intervals=[b-a for a,b in zip(renders,renders[1:])];row={'label':label,'startMs':start,'elapsedMs':end-start,'state':data['state'],'events':events,'longTasks':long,'renderTimes':renders,'frameIntervals':intervals,'heapUsed':page.evaluate('performance.memory?.usedJSHeapSize ?? null')}
 page.screenshot(path=str(out/(label+'.png')),full_page=True);print(label,json.dumps({'elapsed':row['elapsedMs'],'state':row['state'],'geometryMs':[e['duration'] for e in events if e['kind'] in ['geometry','overview']],'longTaskMax':max([e['duration'] for e in long],default=0)},ensure_ascii=False),flush=True);return row
