 page.get_by_label('Date à Nantes',exact=True).fill('2026-06-21');page.locator('.nantes-hour input').evaluate('e=>{e.value=840;e.dispatchEvent(new Event("input",{bubbles:true}))}');idle(page)
 for label,poi in [('B-bouffay','bouffay'),('C-chantenay','chantenay')]:
  start=page.evaluate('performance.now()');page.get_by_role('combobox',name='Choisir un point d’intérêt').select_option(poi);idle(page);rows.append(snap(page,label,start))
 page.get_by_role('combobox',name='Choisir un point d’intérêt').select_option('bouffay');idle(page);start=page.evaluate('performance.now()');page.get_by_role('button',name='Mode piéton',exact=True).click();page.locator('.viewport').scroll_into_view_if_needed();idle(page)
 page.locator('.viewport').focus();page.keyboard.down('w');page.wait_for_timeout(4500);page.keyboard.up('w');idle(page)
 canvas=page.locator('.viewport > canvas');box=canvas.bounding_box();page.mouse.move(box['x']+box['width']*.5,box['y']+box['height']*.5);page.mouse.down();page.mouse.move(box['x']+box['width']*.56,box['y']+box['height']*.5,steps=4);page.mouse.up();idle(page);rows.append(snap(page,'D-walk',start))
 # Départ à proximité d'une vraie limite sur l'allée du Port Maillard.
 page.get_by_role('button',name='Agrandir',exact=True).click();page.wait_for_timeout(200);m=page.evaluate('__map');mapbox=page.locator('.nantes-map canvas').last.bounding_box();px=m['width']/2+(-.6-m['x'])*m['width']/m['span'];py=m['height']/2+(95.4-m['z'])*m['width']/m['span'];page.mouse.click(mapbox['x']+px,mapbox['y']+py);page.get_by_role('button',name='Aller ici',exact=True).click();page.get_by_role('button',name='Réduire',exact=True).click();page.locator('.viewport').scroll_into_view_if_needed();idle(page)
 state=page.evaluate('nantesProfile.snapshot().state');yaw=state['yaw'];target=-1.5707963267948966;delta=(yaw-target+3.141592653589793)%(2*3.141592653589793)-3.141592653589793;box=canvas.bounding_box();x=box['x']+box['width']*.5;y=box['y']+box['height']*.35;page.mouse.move(x,y);page.mouse.down();page.mouse.move(x+delta/.0025,y,steps=4);page.mouse.up();idle(page)
 before=page.evaluate('nantesProfile.snapshot().state.position');start=page.evaluate('performance.now()');page.locator('.viewport').focus();page.keyboard.down('w');page.wait_for_timeout(4500);page.keyboard.up('w');idle(page);row=snap(page,'D-boundary',start);row['positionBefore']=before;row['crossed']=before[0]<0<row['state']['position'][0];rows.append(row)
 page.get_by_role('button',name='Vue aérienne',exact=True).click();page.get_by_role('combobox',name='Choisir un point d’intérêt').select_option('ile');idle(page);start=page.evaluate('performance.now()');page.get_by_label('Circulation',exact=True).select_option('normal');page.get_by_label('Animer l’eau',exact=True).check();page.get_by_role('button',name='▶ Lecture',exact=True).click();page.locator('.viewport').scroll_into_view_if_needed();initial=page.evaluate('__probe.renders.length');page.wait_for_function('(n)=>__probe.renders.length>=n+6',arg=initial);rows.append(snap(page,'E-animated',start));page.get_by_role('button',name='Ⅱ Pause',exact=True).click();page.get_by_label('Circulation',exact=True).select_option('off');page.get_by_label('Animer l’eau',exact=True).uncheck();idle(page)
 page.evaluate("location.hash='#/'");page.wait_for_timeout(500);assert page.locator('canvas').count()==0;assert page.evaluate('__probe.pending.size')==0;assert page.evaluate('!window.nantesProfile');assert not errors,errors;assert not bad,bad
